<script setup lang="ts">
import {computed,onScopeDispose,ref,watch} from 'vue'
import {ApiError,onIdentityChange} from '@/core/http'
import {can,currentProject,projectId,session} from '@/core/session'
import {publicationEnvironmentBoundary} from '../../../../../things-link-console/src/features/ota/firmware-model'
import {otaPublicationTransport,prepareOtaPublication,type OtaPublicationIntent,type OtaPublicationTransport} from './ota-publication-api'
import type {OtaFirmware,OtaUpload,OtaPublication} from './ota-read-api'
const props=withDefaults(defineProps<{disabled?:boolean;firmware?:OtaFirmware;firmwareId?:string;portal?:boolean;target?:HTMLElement;uploads?:readonly OtaUpload[];transport?:OtaPublicationTransport}>(),{transport:()=>otaPublicationTransport})
const emit=defineEmits<{locked:[boolean];changed:[]}>()
const firmwareId=computed(()=>props.firmware?.id??props.firmwareId??'')
const readDenied=ref(false)
const member=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&!!firmwareId.value&&(!props.firmware||props.firmware.projectId===projectId.value)&&['OWNER','ADMIN','OPERATOR','VIEWER'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN','OPERATOR','VIEWER'].includes(currentProject.value?.myRole||''))
const readable=computed(()=>member.value&&!readDenied.value)
const allowed=computed(()=>!readDenied.value&&session.ready&&!session.transitioning&&!!session.user?.accountId&&!!firmwareId.value&&(!props.firmware||props.firmware.projectId===projectId.value)&&props.firmware?.status==='DRAFT'&&currentProject.value?.status==='ACTIVE'&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||'')&&can('ota:deploy'))
const uploads=computed(()=>(props.uploads??[]).filter(row=>row.status==='VERIFIED'&&row.firmwareId===firmwareId.value&&row.projectId===projectId.value))
const text=ref(''),selected=ref(''),busy=ref(false),attempted=ref(false),error=ref(''),result=ref<OtaPublication>()
let alive=true,generation=0,controller:AbortController|undefined,intent:OtaPublicationIntent|undefined
function reset(){generation++;controller?.abort();text.value='';selected.value='';busy.value=false;attempted.value=false;error.value='';result.value=undefined;intent=undefined;readDenied.value=false}
const terminal=computed(()=>!!result.value&&['COMMITTED','REJECTED'].includes(result.value.status)),locked=computed(()=>busy.value||attempted.value&&!terminal.value)
function scopeCurrent(g:number){return alive&&g===generation&&member.value}
function current(g:number){return scopeCurrent(g)&&readable.value}
function denyRead(){if(terminal.value)reset();else{generation++;controller?.abort();busy.value=false;error.value=''}readDenied.value=true}
function match(row:OtaPublication){if(!intent||row.firmwareId!==intent.firmware||row.uploadSessionId!==intent.header.uploadSessionId||result.value&&row.id!==result.value.id)throw new Error('发布记录与本次原意图不一致');return row}
async function reread(){if(props.disabled||!member.value||busy.value||!intent||!attempted.value)return;const g=generation;busy.value=true;error.value='';controller=new AbortController();try{const row=result.value?await props.transport.read(intent.project,intent.firmware,result.value.id,controller.signal):await props.transport.original(intent,controller.signal);if(!scopeCurrent(g))return;result.value=match(row);readDenied.value=false;if(terminal.value)emit('changed')}catch(cause){if(scopeCurrent(g)){if(cause instanceof ApiError&&[401,403].includes(cause.status)){denyRead();return}error.value=cause instanceof ApiError&&cause.status===404?'尚未找到本人原请求键对应的发布记录；原结果仍未知，不会再次提交。':cause instanceof Error?cause.message:'读取发布记录失败'}}finally{if(scopeCurrent(g))busy.value=false}}
async function submit(){if(props.disabled||!allowed.value||busy.value||attempted.value||!props.firmware)return;const upload=uploads.value.find(row=>row.id===selected.value);if(!upload){error.value='请选择已复验的上传会话';return}error.value='';try{intent=prepareOtaPublication(props.firmware,upload,text.value)}catch(cause){error.value=cause instanceof Error?cause.message:'发布清单无效';return}const g=generation;controller=new AbortController();busy.value=true;attempted.value=true;try{const saved=await props.transport.create(intent,controller.signal);if(!current(g))return;result.value=match(saved);const fresh=await props.transport.read(intent.project,intent.firmware,saved.id,controller.signal);if(!current(g))return;result.value=match(fresh);if(terminal.value)emit('changed')}catch(cause){if(!current(g))return;if(result.value&&cause instanceof ApiError&&[401,403].includes(cause.status)){denyRead();return}const boundary=cause instanceof ApiError?publicationEnvironmentBoundary(cause.code,cause.status):null;error.value=boundary==='TRUST_NOT_CONFIGURED'?'当前项目未配置受控发布信任，无法完成签名发布。':boundary==='SIGNER_UNAVAILABLE'?'当前签名服务不可用，未取得固件就绪结果。':'发布结果尚未核实，请按原请求键读取发布记录；不会再次提交。'}finally{if(current(g))busy.value=false}}
watch(locked,value=>emit('locked',value),{immediate:true,flush:'sync'})
let previous:readonly [string,string|undefined,string,OtaPublicationTransport]|undefined
function changedScope(){const same=previous?.[0]===projectId.value&&previous?.[1]===session.user?.accountId&&previous?.[2]===firmwareId.value&&previous?.[3]===props.transport;previous=[projectId.value,session.user?.accountId,firmwareId.value,props.transport];if(same){if((!readable.value||!allowed.value)&&(busy.value||locked.value)){generation++;controller?.abort();busy.value=false}return}reset()}
watch([()=>projectId.value,()=>session.user?.accountId,firmwareId,member,allowed,()=>props.transport],changedScope,{immediate:true,flush:'sync'})
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;reset();dispose();emit('locked',false)})
</script>
<template><Teleport v-if="!portal||target" :to="target||'body'" :disabled="!portal"><p v-if="readDenied" role="alert">当前发布记录读取权限已不可用。<template v-if="attempted">原发布结果仍待核对；恢复读取后只核对原记录。<el-button :disabled="disabled||busy||!member" @click="reread">{{result?'读取原发布记录':'按原请求键读取发布记录'}}</el-button></template></p><section v-if="readable&&(allowed&&props.uploads!==undefined||attempted)" class="firmware-publication"><h3>提交签名发布</h3><p>选择已复验文件并提供发布流程生成的完整清单。提交后需核对服务端结果，不会自动创建升级活动。</p><p v-if="!uploads.length">当前读取的上传记录中没有已复验文件。</p><el-form label-position="top"><el-form-item label="已复验上传会话"><el-select v-model="selected" aria-label="OTA发布上传会话" :disabled="disabled||busy||attempted"><el-option v-for="row in uploads" :key="row.id" :value="row.id" :label="row.id"/></el-select></el-form-item><el-form-item label="发布清单 JSON"><el-input v-model="text" type="textarea" :rows="8" aria-label="OTA发布清单" :disabled="disabled||busy||attempted"/></el-form-item></el-form><el-button v-if="!attempted" type="primary" :disabled="disabled||!selected||!text.trim()||busy" :loading="busy" @click="submit">提交发布</el-button><template v-if="result"><p role="status">发布记录：{{result.id}} · {{result.status}}</p></template><template v-if="attempted"><p>原请求键：{{intent?.key}}</p><el-button :disabled="disabled||busy||!readable" @click="reread">{{result?'读取原发布记录':'按原请求键读取发布记录'}}</el-button></template><p v-if="error" role="alert">{{error}}</p><p v-if="attempted&&!terminal">本次提交已锁定，保留原请求意图；只读取原发布记录，不会再次提交。UNKNOWN 不等于已拒绝或已就绪。</p></section></Teleport></template>
<style scoped>.firmware-publication{margin-top:24px}.firmware-publication p{line-height:1.6;overflow-wrap:anywhere}.firmware-publication .el-select{width:100%}.firmware-publication [role=alert]{color:var(--el-color-danger)}</style>
